import {PEER_KEY,DRAW_KEY,parsePeer,validatePeer,validateDrawBoxes,compareWeek,drawItem,roomCards} from '../core/offline-tools.js';
import {dateKey,addDays} from '../core/model.js';
import {scheduleClock} from '../core/sessions.js';
const E=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const weekdays=['周一','周二','周三','周四','周五','周六','周日'];

export function mountOfflineToolDialogs(){
 if(document.getElementById('compare-sheet'))return;
 const box=document.createElement('div');box.innerHTML=`
 <dialog id="compare-sheet" class="sheet offline-sheet"><div class="sheet-handle"></div><div class="sheet-title"><h2>离线对照课表</h2><button class="plain-icon" data-close="compare-sheet" aria-label="关闭课表对照">✕</button></div><p class="sheet-tip">选择朋友导出的课表 JSON，在本机按实际日期和各自作息对照。朋友调课后，请重新导入新文件。</p><label class="control-label">朋友的称呼<input id="peer-name" maxlength="30" value="朋友"></label><div class="offline-actions"><button id="peer-choose" class="primary-button">选择朋友课表 JSON</button><button id="peer-remove">移除本机朋友课表</button></div><input id="peer-file" type="file" accept="application/json,.json" hidden><p id="peer-error" class="form-error" role="alert"></p><div id="peer-pending" class="offline-pending" hidden></div><div id="peer-saved" class="sheet-tip"></div><div id="compare-controls" hidden><div class="offline-week-nav"><button id="compare-prev" aria-label="前一周">‹</button><strong id="compare-week"></strong><button id="compare-next" aria-label="后一周">›</button></div><div class="offline-compare-filters"><label>开始<input id="compare-start" type="time" value="08:00"></label><label>结束<input id="compare-end" type="time" value="22:00"></label><label>最短空闲<select id="compare-minimum"><option value="10">10分钟</option><option value="20" selected>20分钟</option><option value="30">30分钟</option><option value="60">60分钟</option></select></label></div><p class="sheet-tip">仅表示双方课表未排课，不代表对方实时有空。每个小节之间的课间也按实际钟点计算。</p><div id="compare-days"></div></div></dialog>
 <dialog id="room-sheet" class="sheet room-sheet"><div class="sheet-handle"></div><div class="sheet-title"><h2>下一节教室</h2><button class="plain-icon" data-close="room-sheet" aria-label="关闭教室卡片">✕</button></div><div class="room-date-switch"><button id="room-today">今天</button><button id="room-tomorrow">明天</button></div><p id="room-date" class="sheet-tip"></p><div id="room-content" role="status" aria-live="polite"></div><div class="room-card-nav"><button id="room-prev" aria-label="上一堂课">‹ 上一堂</button><span id="room-count"></span><button id="room-next" aria-label="下一堂课">下一堂 ›</button></div><p class="sheet-tip">按本机时间与已保存作息判断。左右滑动卡片也可切换。</p></dialog>
 <dialog id="draw-sheet" class="sheet offline-sheet"><div class="sheet-handle"></div><div class="sheet-title"><h2>本地抽签盒</h2><button class="plain-icon" data-close="draw-sheet" aria-label="关闭抽签盒">✕</button></div><p class="sheet-tip">把想吃的、想玩的或其他选项放进列表，犹豫时抽一个。内容只保存在本机。</p><label class="control-label">选择列表<select id="draw-list"></select></label><div class="offline-actions"><button id="draw-new">新建列表</button><button id="draw-delete">删除当前列表</button></div><form id="draw-form" class="offline-draw-form"><label>列表名称<input id="draw-name" maxlength="40" required placeholder="例如：午饭吃什么"></label><label>选项，每行一个<textarea id="draw-items" rows="6" placeholder="饭\n面\n饺子"></textarea></label><p class="sheet-tip">每个列表最多100项，每项100字；重复选项自动合并。</p><button class="primary-button" type="submit">保存列表</button></form><p id="draw-error" class="form-error" role="alert"></p><div id="draw-result" class="draw-result" role="status" aria-live="polite">先保存一个列表</div><div class="offline-actions"><button id="draw-pick" class="primary-button">抽一个</button><button id="draw-clear-result">清除结果</button></div><p id="draw-count" class="sheet-tip"></p></dialog>`;
 while(box.firstElementChild)document.body.append(box.firstElementChild);
}

export function setupOfflineTools({get,notify=()=>{},openSheet}){
 mountOfflineToolDialogs();const $=selector=>document.querySelector(selector);let peer=null,pending=null,compareSelected=1,draw=validateDrawBoxes(),drawEditingNew=false,roomOffset=0,roomIndex=0,roomManual=false,roomTimer=0,roomList=[];
 try{const raw=localStorage.getItem(PEER_KEY);if(raw)peer=validatePeer(JSON.parse(raw));}catch{$('#peer-error').textContent='本机朋友课表暂时无法读取，可重新导入文件。';}
 try{const raw=localStorage.getItem(DRAW_KEY);if(raw)draw=validateDrawBoxes(JSON.parse(raw));}catch{$('#draw-error').textContent='本机抽签列表暂时无法读取；保存新列表会替换此记录。';}
 function saveDraw(next){const checked=validateDrawBoxes(next);localStorage.setItem(DRAW_KEY,JSON.stringify(checked));draw=checked;}
 function openCompare(){compareSelected=get().week;$('#peer-name').value=peer?.name||'朋友';renderCompare();openSheet('#compare-sheet');}
 function renderCompare(){
  const {settings,courses}=get();compareSelected=Math.max(1,Math.min(settings.totalWeeks,compareSelected));$('#compare-controls').hidden=!peer;$('#peer-remove').disabled=!peer;
  $('#peer-saved').textContent=peer?`${peer.name} · ${peer.envelope.settings.term} · 第一周 ${peer.envelope.settings.startDate} · ${peer.envelope.courses.length} 条排课`:'尚未导入朋友课表。自己的课表不会被替换。';if(!peer)return;
  $('#compare-week').textContent='我的第 '+compareSelected+' 周';$('#compare-prev').disabled=compareSelected<=1;$('#compare-next').disabled=compareSelected>=settings.totalWeeks;
  try{const result=compareWeek({settings,courses},peer.envelope,compareSelected,{start:$('#compare-start').value,end:$('#compare-end').value,minimum:Number($('#compare-minimum').value)});$('#peer-error').textContent='';
   const courseLine=(c,times)=>`<li class="${c.cancelled?'offline-cancelled':''}">${E(c.name)}<small>${times[c.start-1].split('-')[0]}–${times[c.end-1].split('-')[1]}${c.location?' · '+E(c.location):''}${c.cancelled?' · 停课':''}</small></li>`;
   $('#compare-days').innerHTML=result.days.map((day,i)=>`<section class="offline-day"><h3>${weekdays[i]} <span>${day.date.slice(5)}</span></h3>${day.known?`<p class="offline-day-week">我的第${day.ownWeek}周 · ${E(peer.name)}第${day.peerWeek}周</p><div class="free-periods">${day.free.length?day.free.map(f=>`<span>${f.start}–${f.end}<small>${f.minutes}分钟</small></span>`).join(''):'<p>所选时段内，没有达到最短长度的共同空闲。</p>'}</div>`:'<p class="offline-coverage">这一天不在双方课表的共同学期范围内，不能确认空闲。</p>'}<details><summary>查看双方课程</summary><div class="offline-both"><div><b>我</b><ul>${day.own.length?day.own.map(c=>courseLine(c,settings.times)).join(''):'<li>该日无排课记录</li>'}</ul></div><div><b>${E(peer.name)}</b><ul>${day.peer.length?day.peer.map(c=>courseLine(c,peer.envelope.settings.times)).join(''):'<li>该日无排课记录</li>'}</ul></div></div></details></section>`).join('');
  }catch(error){$('#peer-error').textContent=error.message;$('#compare-days').replaceChildren();}
 }
 $('#peer-choose').onclick=()=>$('#peer-file').click();$('#peer-file').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;$('#peer-error').textContent='';try{if(file.size>2*1024*1024)throw Error('课表 JSON 最大2MB');const value=parsePeer(JSON.parse(await file.text()),$('#peer-name').value);pending=value;$('#peer-pending').hidden=false;$('#peer-pending').innerHTML=`<strong>核对朋友课表</strong><p>${E(value.name)} · ${E(value.envelope.settings.term)}<br>第一周 ${value.envelope.settings.startDate} · ${value.envelope.courses.length} 条排课</p><div class="offline-actions"><button id="peer-confirm" class="primary-button">保存到本机并对照</button><button id="peer-cancel">取消</button></div>`;$('#peer-confirm').onclick=()=>{try{if(!pending)return;localStorage.setItem(PEER_KEY,JSON.stringify(pending));peer=pending;pending=null;$('#peer-pending').hidden=true;renderCompare();notify('朋友课表已保存在本机，自己的课表保持原样');}catch(error){$('#peer-error').textContent=error.message;}};$('#peer-cancel').onclick=()=>{pending=null;$('#peer-pending').hidden=true;};}catch(error){pending=null;$('#peer-pending').hidden=true;$('#peer-error').textContent='读取失败：'+error.message;}};
 $('#peer-remove').onclick=()=>{try{localStorage.removeItem(PEER_KEY);peer=null;pending=null;$('#peer-pending').hidden=true;renderCompare();notify('已移除本机朋友课表');}catch(error){$('#peer-error').textContent=error.message;}};
 $('#peer-name').onchange=()=>{if(!peer)return;try{const checked=validatePeer({...peer,name:$('#peer-name').value});localStorage.setItem(PEER_KEY,JSON.stringify(checked));peer=checked;$('#peer-name').value=peer.name;renderCompare();}catch(error){$('#peer-error').textContent=error.message;}};
 $('#compare-prev').onclick=()=>{compareSelected--;renderCompare();};$('#compare-next').onclick=()=>{compareSelected++;renderCompare();};for(const id of ['compare-start','compare-end','compare-minimum'])$('#'+id).onchange=renderCompare;
 $('#compare-sheet').addEventListener('close',()=>{pending=null;$('#peer-pending').hidden=true;});

 function renderDraw(){const list=draw.lists.find(x=>x.id===draw.selectedId);$('#draw-list').innerHTML=draw.lists.length?draw.lists.map(x=>`<option value="${E(x.id)}" ${x.id===draw.selectedId?'selected':''}>${E(x.name)}</option>`).join(''):'<option value="">尚无列表</option>';$('#draw-list').disabled=!draw.lists.length;$('#draw-delete').disabled=!list;$('#draw-pick').disabled=!list?.items.length;$('#draw-count').textContent=list?`${draw.lists.length}/20个列表 · 当前${list.items.length}个选项`:'可以先新建一个列表。';if(!drawEditingNew){$('#draw-name').value=list?.name||'';$('#draw-items').value=list?.items.join('\n')||'';}}
 $('#draw-new').onclick=()=>{if(draw.lists.length>=20){$('#draw-error').textContent='最多保存20个列表，请先删除不需要的列表';return;}drawEditingNew=true;$('#draw-form').reset();$('#draw-delete').disabled=true;$('#draw-pick').disabled=true;$('#draw-error').textContent='填写并保存后才创建新列表';$('#draw-name').focus();};
 $('#draw-list').onchange=()=>{try{saveDraw({...draw,selectedId:$('#draw-list').value});drawEditingNew=false;$('#draw-error').textContent='';$('#draw-result').textContent='点「抽一个」开始';renderDraw();}catch(error){$('#draw-error').textContent=error.message;}};
 $('#draw-form').onsubmit=event=>{event.preventDefault();try{const name=$('#draw-name').value.trim(),rawItems=$('#draw-items').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!name)throw Error('请填写列表名称');if(rawItems.length>100)throw Error('每个列表最多100项');if(rawItems.some(x=>x.length>100))throw Error('每个选项最多100字');const items=[...new Set(rawItems)],id=drawEditingNew||!draw.selectedId?crypto.randomUUID():draw.selectedId;const lists=draw.lists.filter(x=>x.id!==id);lists.push({id,name,items});saveDraw({version:1,selectedId:id,lists});drawEditingNew=false;$('#draw-error').textContent='';$('#draw-result').textContent=items.length?'已保存，点「抽一个」开始':'列表已保存，添加选项后即可抽签';renderDraw();notify('抽签列表已保存');}catch(error){$('#draw-error').textContent=error.message;}};
 $('#draw-delete').onclick=()=>{try{saveDraw({...draw,lists:draw.lists.filter(x=>x.id!==draw.selectedId)});drawEditingNew=false;$('#draw-result').textContent='已删除列表';$('#draw-error').textContent='';renderDraw();}catch(error){$('#draw-error').textContent=error.message;}};
 $('#draw-pick').onclick=()=>{try{const list=draw.lists.find(x=>x.id===draw.selectedId);if(!list)throw Error('先保存一个列表');$('#draw-result').textContent=drawItem(list.items);$('#draw-error').textContent=list.items.length===1?'列表只有一个选项，因此结果就是它。':'';}catch(error){$('#draw-error').textContent=error.message;}};
 $('#draw-clear-result').onclick=()=>{$('#draw-result').textContent='点「抽一个」开始';$('#draw-error').textContent='';};

 function renderRoom(){clearTimeout(roomTimer);if(!$('#room-sheet').open)return;const now=new Date(),{courses,settings}=get(),date=addDays(now,roomOffset),clock=scheduleClock(courses,settings,now);roomList=roomCards(courses,settings,date);
  if(!roomManual){const active=clock.current[0]||clock.next[0];roomIndex=active&&active.date===dateKey(date)?Math.max(0,roomList.findIndex(c=>c.id===active.id&&active.period>=c.start&&active.period<=c.end)):0;}
  roomIndex=Math.max(0,Math.min(roomList.length-1,roomIndex));$('#room-date').textContent=(roomOffset===0?'今天':'明天')+' · '+dateKey(date)+' '+weekdays[(date.getDay()+6)%7];$('#room-today').classList.toggle('selected',roomOffset===0);$('#room-tomorrow').classList.toggle('selected',roomOffset===1);
  const c=roomList[roomIndex];if(c){const current=clock.current.some(x=>x.id===c.id&&x.date===c.date&&x.period>=c.start&&x.period<=c.end),next=clock.next.some(x=>x.id===c.id&&x.date===c.date&&x.period>=c.start&&x.period<=c.end),first=clock.today.find(x=>x.id===c.id&&x.period===c.start),last=clock.today.find(x=>x.id===c.id&&x.period===c.end),inBlock=first&&last&&now.getTime()>=first.startsAt&&now.getTime()<last.endsAt,status=c.cancelled?'这堂课已停课':current?'正在上课':roomOffset===0&&inBlock&&clock.onBreak?'课间休息':next?'下一节':roomOffset===1?'明天的课程':last&&now.getTime()>=last.endsAt?'已结束':'待上课';
   $('#room-content').innerHTML=`<div class="room-status">${status}</div><strong class="room-location">${E(c.location||'地点待定')}</strong><h3>${E(c.name)}</h3><p>第${c.start===c.end?c.start:c.start+'–'+c.end}节 · ${c.time}</p>${c.teacher?`<small>${E(c.teacher)}</small>`:''}`;
  }else{const next=clock.next[0];$('#room-content').innerHTML=`<div class="room-empty">${roomOffset===0?'今天':'明天'}没有排课</div><p>${next?'下一次：'+E(next.date+' '+next.time+' · '+next.name+' · '+(next.location||'地点待定')):'未来7天没有课程'}</p>`;}
  $('#room-count').textContent=roomList.length?`${roomIndex+1} / ${roomList.length}`:'—';$('#room-prev').disabled=roomIndex<=0;$('#room-next').disabled=roomIndex>=roomList.length-1;
  if(!document.hidden){const stamp=now.getTime(),changes=[stamp+60000-stamp%60000,...clock.current.map(c=>c.endsAt),...clock.next.map(c=>c.startsAt)].filter(x=>x>stamp);roomTimer=setTimeout(renderRoom,Math.max(80,Math.min(...changes)-stamp+30));}
 }
 function openRoom(){roomOffset=0;roomIndex=0;roomManual=false;openSheet('#room-sheet');renderRoom();}
 function roomStep(delta){roomManual=true;roomIndex+=delta;renderRoom();}
 $('#room-today').onclick=()=>{roomOffset=0;roomManual=false;renderRoom();};$('#room-tomorrow').onclick=()=>{roomOffset=1;roomManual=false;renderRoom();};$('#room-prev').onclick=()=>roomStep(-1);$('#room-next').onclick=()=>roomStep(1);$('#room-sheet').addEventListener('close',()=>clearTimeout(roomTimer));
 let swipe=null;$('#room-content').addEventListener('pointerdown',e=>{swipe={x:e.clientX,y:e.clientY};});$('#room-content').addEventListener('pointerup',e=>{if(!swipe)return;const dx=e.clientX-swipe.x,dy=e.clientY-swipe.y;swipe=null;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.5)roomStep(dx<0?1:-1);});$('#room-content').addEventListener('pointercancel',()=>swipe=null);
 document.addEventListener('visibilitychange',()=>{clearTimeout(roomTimer);if(!document.hidden&&$('#room-sheet').open)renderRoom();});
 const entries=[['compare','离线对照朋友课表','两份课表 · 共同空闲'],['room-card','下一节教室','大字卡片 · 今天与明天'],['draw-box','本地抽签盒','自建列表 · 抽一个']];
 for(const selector of ['#menu-sheet','#user-view']){const host=$(selector);if(!host)continue;const section=document.createElement('section');section.className='offline-tools-entries';section.setAttribute('aria-label','离线小工具');section.innerHTML=entries.map(([action,title,sub])=>`<button class="action-row" type="button" data-action="${action}"><span class="offline-entry-symbol" aria-hidden="true">${action==='compare'?'▦':action==='room-card'?'⌖':'◇'}</span><span>${title}<small>${sub}</small></span><span aria-hidden="true">›</span></button>`).join('');if(selector==='#menu-sheet')host.querySelector('[data-action="updates"]')?.before(section);else host.append(section);}
 if($('#live-status')){const button=document.createElement('button');button.id='room-shortcut';button.type='button';button.className='room-shortcut';button.dataset.action='room-card';button.textContent='下一节教室 ↗';$('#live-status').after(button);}
 document.addEventListener('click',event=>{const action=event.target.closest('[data-action]')?.dataset.action;if(action==='compare')openCompare();else if(action==='room-card')openRoom();else if(action==='draw-box'){drawEditingNew=false;renderDraw();openSheet('#draw-sheet');}});
 function checkHash(){if(location.hash!=='#room')return;history.replaceState(history.state,'',location.pathname+location.search);openRoom();}window.addEventListener('hashchange',checkHash);queueMicrotask(checkHash);
 renderDraw();return {openRoom,openCompare,refresh(){if($('#room-sheet').open)renderRoom();if($('#compare-sheet').open)renderCompare();}};
}
